INSERT INTO "public"."ai_rag_chunk" VALUES (2116096310049873923, 2101955528208506881, 5, '9.3晾晒与贮藏:收获后及时晾晒,籽粒水分降至13%以下方可入库贮藏。清理杂质、霉变粒、破损
粒,贮藏仓库干燥、通⻛、防潮、防虫、防鼠,定期检查,防止发热、霉变、虫蛀。
10生产记录管理
规模化种植需建立完整种植档案,详细记录品种、播种时间、施肥种类与用量、用药时间与药剂、浇
水情况、病虫害发生、收获时间等信息,实现全程可追溯,保障玉米产品质量安全。
11附则
